<?php
if(!defined('SERVICES')||empty($_SESSION['user_id'])){http_response_code(404);exit;}
$ownReview=null;$ownReviewUnavailable=false;
try{$stmt=db()->prepare('SELECT rating,comment,created_at,updated_at FROM reviews WHERE user_id=?');$stmt->execute([$_SESSION['user_id']]);$ownReview=$stmt->fetch();}
catch(Throwable $e){error_log($e->getMessage());$ownReviewUnavailable=true;}
$ownDraft=$_SESSION['review_draft']??($ownReview?:['rating'=>5,'comment'=>'']);
$ownError=$_SESSION['review_error']??'';$ownSuccess=$_SESSION['review_success']??'';
unset($_SESSION['review_draft'],$_SESSION['review_error'],$_SESSION['review_success']);
?>
<section class="panel customer-review-panel" id="my-review" aria-labelledby="my-review-title"><div class="panel-title"><h2 id="my-review-title">My Review</h2><a class="refresh-appointments" href="index.php#reviews">View customer reviews ↗</a></div><p class="appointments-intro">Share your experience or refresh your existing review. Your name, rating and comment appear publicly on our website.</p><?php if($ownReviewUnavailable): ?><p role="alert">Your review is temporarily unavailable. Please refresh and try again.</p><?php else: ?>
<div class="customer-review-grid"><div class="my-review-preview"><?php if($ownReview): ?><p class="eyebrow">YOUR PUBLISHED REVIEW</p><div class="review-card-top"><span class="review-avatar" aria-hidden="true"><?=h($initial)?></span><div><h3><?=h($user['name'])?></h3><p class="review-small">Updated <?=h(date('d M Y',strtotime($ownReview['updated_at'])))?></p></div></div><div class="review-stars" aria-label="<?=h($ownReview['rating'])?> out of 5 stars"><span aria-hidden="true"><?=str_repeat('★',(int)$ownReview['rating'])?><span class="unfilled-stars"><?=str_repeat('★',5-(int)$ownReview['rating'])?></span></span></div><p class="review-comment"><?=nl2br(h($ownReview['comment']))?></p><?php else: ?><span class="my-review-empty-icon" aria-hidden="true">✎</span><h3>Your experience matters.</h3><p class="appointments-intro">You haven’t posted a review yet. Tell us about your visit using the form.</p><?php endif; ?></div>
<div class="write-review dashboard-review-form"><h3><?=$ownReview?'Update your review':'Write your first review'?></h3><?php if($ownError): ?><p class="review-error" role="alert"><?=h($ownError)?></p><?php endif; ?><?php if($ownSuccess): ?><p class="review-success" role="status"><?=h($ownSuccess)?></p><?php endif; ?><form method="post" action="submit-review.php"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="return_to" value="account"><label for="account-rating">Your rating</label><select name="rating" id="account-rating" required><?php for($star=5;$star>=1;$star--): ?><option value="<?=$star?>" <?=(int)$ownDraft['rating']===$star?'selected':''?>><?=$star?> / 5 — <?=['','Poor','Fair','Good','Very good','Excellent'][$star]?></option><?php endfor; ?></select><label for="account-comment">Your comment</label><textarea name="comment" id="account-comment" rows="5" minlength="10" maxlength="2000" required placeholder="Tell us about your experience."><?=h($ownDraft['comment'])?></textarea><p class="review-small">10–2,000 characters. Please leave out private contact details. One review per account; updates replace your previous review.</p><button class="button" type="submit"><?=$ownReview?'Update my review':'Publish my review'?> <span>↗</span></button></form></div></div><?php endif; ?></section>
